  id: string;
  title: string;
  instruction: string;
  validation: ValidationRule[];
  startingCode?: string;
  solution?: string;
}

export interface Exercise {
  id: string;
  title: string;
  module: string;
  description: string;
  instruction: string;
  startingCode?: string;
  solution?: string;
