display.text:
slug: events
title: Events
moduleName: Interaction
description: "Make your sketches respond to mouse clicks, key presses, and touch."
exercises:
  - id: exercise-1
    title: "Click to Draw"
    module: Events
    description: "Draw a circle where the user clicks using mousePressed()."
    instruction: |
      Define a mousePressed() function that draws a circle at mouseX, mouseY.
      Each time you tap the canvas, a new circle appears.
    startingCode: |
      function setup() {
