slug: image
title: Image
moduleName: Visual Media
description: "Create, display, and manipulate images on the canvas."

exercises:
  - id: exercise-1
    title: "Pixel Canvas"
    module: Image
    description: "Create an image from scratch by setting individual pixels."
    instruction: |
      Create a 100x100 image and fill the top half with red.
      Use createImage(w, h) to make the image,
      set(x, y, color) to set a red pixel, then updatePixels().
    startingCode: |
      function setup() {
        createCanvas(400, 400);
      }

      function draw() {
        background(240);
        let img = createImage(100, 100);
      }
    solution: |
      function setup() {
        createCanvas(400, 400);
      }

      function draw() {
        background(240);
        let img = createImage(100, 100);
        img.loadPixels();
        for (let x = 0; x < 100; x++) {
          for (let y = 0; y < 50; y++) {
            img.set(x, y, color(255, 0, 0));
          }
        }
        img.updatePixels();
        image(img, 150, 150);
      }
    tasks:
      - id: task-1
        title: "Create an Image"
        instruction: |
          Create a 100x100 image using createImage(100, 100).
        validation:
          - type: functionCall
            name: createImage
            exactArgs: 2
      - id: task-2
        title: "Set Pixels"
        instruction: |
          Call loadPixels() on the image, then use a loop to set pixels in the top half (y < 50) to red using set(x, y, color(255, 0, 0)).
          Finish with updatePixels().
        validation:
          - type: functionCall
            name: createImage
            exactArgs: 2
          - type: functionCall
            name: loadPixels
            exactArgs: 0
          - type: functionCall
            name: set
            minArgs: 3
          - type: functionCall
            name: updatePixels
            exactArgs: 0
          - type: functionCall
            name: image
            exactArgs: 3

  - id: exercise-2
    title: "Image Tint"
    module: Image
    description: "Display an image with a color tint."
    instruction: |
      Create a colored image and display it with a tint.
      Use createImage(w, h), fill it with a color, then use
      tint(r, g, b) before image(img, x, y).
    startingCode: |
      function setup() {
        createCanvas(400, 400);
      }

      function draw() {
        background(240);
        let img = createImage(100, 100);
      }
    solution: |
      function setup() {
        createCanvas(400, 400);
      }

      function draw() {
        background(240);
        let img = createImage(100, 100);
        img.loadPixels();
        for (let i = 0; i < img.width * img.height; i++) {
          img.pixels[i * 4] = 255;
          img.pixels[i * 4 + 1] = 255;
          img.pixels[i * 4 + 2] = 255;
          img.pixels[i * 4 + 3] = 255;
        }
        img.updatePixels();
        tint(255, 200, 0);
        image(img, 150, 150);
      }
    tasks:
      - id: task-1
        title: "Display Image"
        instruction: |
          Create a 100x100 image, fill all pixels white (255, 255, 255), and display it with image(img, 150, 150).
        validation:
          - type: functionCall
            name: createImage
            exactArgs: 2
          - type: functionCall
            name: image
            exactArgs: 3
      - id: task-2
        title: "Apply Tint"
        instruction: |
          Use tint(255, 200, 0) before the image() call to tint the image yellow.
        validation:
          - type: functionCall
            name: createImage
            exactArgs: 2
          - type: functionCall
            name: tint
            exactArgs: 3
          - type: functionCall
            name: image
            exactArgs: 3
          - type: pixelMatch
            x: 200
            y: 200
