        stroke(255, 100, 100);
        strokeWeight(1);
        for (let i = 1; i < 10; i++) {
          let t = i / 10;
          let px = bezierPoint(x1, x2, x3, x4, t);
          let py = bezierPoint(y1, y2, y3, y4, t);
          // Compute tangent and draw a line
        }
      }
    solution: |
      function setup() {
        createCanvas(400, 400);
      }

      function draw() {
        background(20);
        stroke(100, 255, 180);
        strokeWeight(2);
        noFill();

        let x1 = 50, y1 = 300;
        let x2 = 150, y2 = 50;
        let x3 = 250, y3 = 350;
        let x4 = 350, y4 = 100;

        bezier(x1, y1, x2, y2, x3, y3, x4, y4);

        stroke(255, 100, 100);
        strokeWeight(1);
        for (let i = 1; i < 10; i++) {
          let t = i / 10;
          let px = bezierPoint(x1, x2, x3, x4, t);
          let py = bezierPoint(y1, y2, y3, y4, t);
          let tx = bezierTangent(x1, x2, x3, x4, t);
          let ty = bezierTangent(y1, y2, y3, y4, t);
          let len = 20;
          line(px, py, px + tx * len, py + ty * len);
