          Store them as tx and ty.
        validation:
          - type: functionCall
            name: bezierTangent
            exactArgs: 5
          - type: functionCall
            name: bezierPoint
            exactArgs: 5
      - id: task-2
        title: "Draw Tangent Lines"
        instruction: |
          Draw a line from each point on the curve in the tangent direction.
          Use line(px, py, px + tx * 20, py + ty * 20) to extend 20 pixels along the tangent.
        validation:
          - type: functionCall
            name: bezierTangent
            exactArgs: 5
          - type: functionCall
            name: line
            exactArgs: 4
          - type: pixelMatch
