  - id: exercise-2
    title: "Pulsing Circle"
    module: Time & Date
    description: "Create a pulsing circle using sin() with millis()."
    instruction: |
      Use sin(millis() / 500) to create a pulsing effect.
      Map the result to a diameter between 50 and 200 using map().
    startingCode: |
      function setup() {
        createCanvas(400, 400);
      }

      function draw() {
        background(240);
        fill(100, 200, 255);
      }
    solution: |
      function setup() {
        createCanvas(400, 400);
      }

      function draw() {
        background(240);
        let pulse = sin(millis() / 500);
        let d = map(pulse, -1, 1, 50, 200);
        fill(100, 200, 255);
        circle(200, 200, d);
      }
    tasks:
      - id: task-1
        title: "Pulsing Effect"
        instruction: |
          Use let pulse = sin(millis() / 500) and let d = map(pulse, -1, 1, 50, 200) to animate circle size.
        validation:
          - type: functionCall
            name: sin
            exactArgs: 1
          - type: functionCall
            name: millis
            exactArgs: 0
          - type: functionCall
            name: map
            exactArgs: 5
  - id: exercise-3
    title: "Frame Counter"
    module: Time & Date
    description: "Display the frame count and create frame-based animation."
    instruction: |
      Display frameCount as text on screen.
      Also use frameCount to rotate a rectangle: rotate(frameCount * 0.02).
    startingCode: |
      function setup() {
        createCanvas(400, 400);
      }

      function draw() {
        background(240);
        fill(0);
