        createCanvas(400, 400);
      }

      function draw() {
        background(240);
        fill(0);
        textSize(18);
        text("Frame: " + frameCount, 50, 50);
        push();
        translate(200, 200);
        rotate(frameCount * 0.02);
        fill(255, 100, 50);
        rectMode(CENTER);
        rect(0, 0, 100, 100);
        pop();
      }
    tasks:
      - id: task-1
        title: "Frame-Based Rotation"
