     html += `<span class="symbol" data-symbol="${match[0]}">${match[0]}</span>`;
     lastIndex = match.index + match[0].length;
   }

   if (lastIndex < text.length) {
     html += escapeHtml(text.slice(lastIndex));
   }

   return html || escapeHtml(text);
 }

