const STD_GLOBALS = new Set([
  "console", "window", "document", "Math", "JSON", "parseInt", "parseFloat",
  "String", "Number", "Boolean", "Array", "Object", "Promise", "Date",
  "alert", "setTimeout", "setInterval", "clearTimeout", "clearInterval",
  "requestAnimationFrame", "fetch", "navigator", "localStorage",
]);

function stripIgnored(src) { ... same as check-exercises ... }

function extractIdentifiers(code) {
  const sanitized = stripIgnored(code);
  const out = new Set();
  const re = /\b([A-Za-z_$][\w$]*)\s*\(/g;
  let m;
  while ((m = re.exec(sanitized)) !== null) {
    const idx = m.index;
    // Skip calls that are member access: `foo.bar(` or `foo?.bar(` or `foo.bar.baz(`
    let j = idx - 1;
    while (j >= 0 && (sanitized[j] === " " || sanitized[j] === "\t" || sanitized[j] === "\n")) j--;
    if (j >= 0 && sanitized[j] === ".") {
      // walk back to start of the member chain to make sure the base isn't a call target
      continue;
    }
    out.add(m[1]);
  }
  return out;
}
