     solution: |
       function setup() {
         createCanvas(400, 400);
       }

       function draw() {
         background(240);
         fill(50, 220, 150);
         push();
         translate(200, 200);
         scale(2);
         rectMode(CENTER);
         rect(0, 0, 50, 50);
         pop();
       }
     tasks:
       - id: task-1
         title: "Scale a Rectangle"
         instruction: |
           Use push(), translate(200, 200), scale(2), rectMode(CENTER), rect(0, 0, 50, 50), pop().
         validation:
           - type: functionCall
