             minArgs: 1
           - type: functionCall
             name: push
             exactArgs: 0
           - type: functionCall
             name: pop
             exactArgs: 0
   - id: exercise-4
     title: "State Stack"
     module: Transform
     description: "Use push() and pop() to isolate transforms between multiple shapes."
     instruction: |
       Draw two rectangles with different transforms.
       First: translate(100, 200) + rotate(PI/6), wrapped in push/pop.
       Second: translate(300, 200) + scale(1.5), wrapped in push/pop.
     startingCode: |
       function setup() {
