slug: custom-shapes
title: Custom Shapes
moduleName: Drawing
description: "Build custom shapes with vertex-based drawing using beginShape() and endShape()."

exercises:
  - id: exercise-1
    title: "Vertex Playground"
    module: Drawing
    description: "Use beginShape(), vertex(), and endShape() to draw a custom polygon."
    instruction: |
      Draw a triangle using vertex coordinates.
      Use beginShape(), three vertex(x, y) calls, and endShape(CLOSE).
      Vertices: (200, 60), (80, 340), (320, 340).
    startingCode: |
      function setup() {
        createCanvas(400, 400);
      }

      function draw() {
        background(30);
        fill(100, 200, 255);
        stroke(255);
        strokeWeight(2);
        beginShape();
        // Add your vertices here
        endShape(CLOSE);
      }
    solution: |
      function setup() {
        createCanvas(400, 400);
      }

      function draw() {
        background(30);
        fill(100, 200, 255);
        stroke(255);
        strokeWeight(2);
        beginShape();
        vertex(200, 60);
        vertex(80, 340);
        vertex(320, 340);
        endShape(CLOSE);
      }
    tasks:
      - id: task-1
        title: "Add Vertex Calls"
        instruction: |
          Add three vertex(x, y) calls between beginShape() and endShape(CLOSE).
          Use (200, 60), (80, 340), and (320, 340).
        validation:
          - type: functionCall
            name: beginShape
            exactArgs: 0
          - type: functionCall
            name: vertex
            exactArgs: 2
          - type: functionCall
