  solution: |
    function setup() {
      createCanvas(400, 400);
    }

    function draw() {
      background(35);
      fill(255, 200, 80);
      let a = createVector(300, 100);
      let b = createVector(100, 200);
      a.sub(b);
      a.mult(1.5);
      circle(a.x, a.y, 50);
